// single-item input: the form emits one submission and this fans it out into
// one search per advertiser, which is what the loop below consumes.
//
// Two sides go into the same loop rather than two parallel branches: the
// comparison downstream only works if both sides were read the same way, in the
// same country, on the same day.
const form = $('Brief Me On A Competitor').first().json;
const cfg = $('Settings').first().json;

const them = String(form['Competitor brand or category'] || '').trim();
const us = String(form['Your own brand (optional)'] || '').trim();

if (!them) {
  throw new Error('Enter at least a competitor brand or a category to search for.');
}

const country = String(form['Country'] || 'US').toUpperCase().slice(0, 2);

function url(term) {
  // active_status=active is deliberate. An inactive ad is a campaign that
  // already ended, which is history rather than competitive intelligence.
  return 'https://www.facebook.com/ads/library/?active_status=active&ad_type=all' +
    '&country=' + encodeURIComponent(country) +
    '&q=' + encodeURIComponent(term) +
    '&search_type=keyword_unordered&media_type=all';
}

const rows = [];
// Comma-separated is allowed on the competitor field, so one run can cover a
// category and the two names in it.
for (const t of them.split(',').map((s) => s.trim()).filter(Boolean).slice(0, 6)) {
  rows.push({ json: { term: t, side: 'them', country, ad_library_url: url(t) } });
}
if (us) {
  rows.push({ json: { term: us, side: 'us', country, ad_library_url: url(us) } });
}

return rows;

// One markdown blob in, one item per ad card out.
//
// The response is the rendered Ad Library page as markdown. Cards are separated
// by their `Library ID:` line, so splitting on that gives one chunk per ad -
// with one catch that cost a rewrite: the Active/Inactive flag is printed
// *above* the id, so it belongs to the previous chunk, not this one.
//
// single-item input: the loop hands over one term's response at a time, so
// there is exactly one page of markdown to read here.
const loopItem = $('Loop Over Advertisers').first().json;
const term = loopItem.term;
// `side` and `country` travel with the card from here on. Without that the
// comparison downstream has no way to tell whose ad it is looking at, and it
// reported zero on both sides while every node stayed green.
const side = loopItem.side || 'them';
const country = loopItem.country || '';
const raw = $input.first().json;
const md = typeof raw === 'string' ? raw : (raw.data || raw.body || '');

if (!md || md.length < 500) {
  return [{ json: { term: term, side: side, country: country, ads_found: 0, note: 'Ad Library returned nothing readable' } }];
}
// Bright Data answers errors with HTTP 200 and an error body, and this node
// runs with neverError, so an unchecked response looks like a success.
if (md.indexOf('"error"') !== -1 && md.length < 2000) {
  throw new Error('Bright Data returned an error for ' + term + ': ' + md.slice(0, 300));
}

const MONTHS = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };
const today = new Date();

// The grid header reports the size of the whole result set, which is the
// difference between watching a competitor and watching a category.
const totalMatch = md.match(/~?([\d,]+)\s+results/i);
const totalResults = totalMatch ? Number(totalMatch[1].replace(/,/g, '')) : 0;

// No URL constructor in the Code node sandbox, so query strings come apart by
// regex. decodeURIComponent is available and is what unwraps the redirect.
function unwrap(chunk) {
  const m = chunk.match(/l\.facebook\.com\/l\.php\?u=([^&"'\s)]+)/);
  if (!m) return '';
  try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
}
function param(url, key) {
  const m = String(url).match(new RegExp('[?&]' + key + '=([^&]*)'));
  if (!m) return '';
  try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
}

const parts = md.split('Library ID:');
const out = [];
const seen = {};

for (let i = 1; i < parts.length; i++) {
  const before = parts[i - 1];
  const chunk = parts[i];

  const idMatch = chunk.match(/^\s*(\d{6,})/);
  if (!idMatch) continue;
  const libraryId = idMatch[1];
  if (seen[libraryId]) continue;
  seen[libraryId] = true;

  // Status lives in the tail of the previous card's chunk.
  const statusMatches = before.slice(-400).match(/\b(Active|Inactive)\b/g);
  const status = statusMatches ? statusMatches[statusMatches.length - 1] : '';

  let startedOn = '';
  let daysRunning = 0;
  const d = chunk.match(/Started running on ([A-Z][a-z]{2}) (\d{1,2}), (\d{4})/);
  if (d) {
    const dt = new Date(Number(d[3]), MONTHS[d[1]], Number(d[2]));
    startedOn = dt.toISOString().slice(0, 10);
    daysRunning = Math.max(0, Math.round((today - dt) / 86400000));
  }

  const adv = chunk.match(/\n\[([^\]]{1,80})\]\((https:\/\/www\.facebook\.com\/[^)]+)\)/);

  // The primary text sits between the Sponsored marker and the creative block.
  let body = '';
  const s = chunk.indexOf('**Sponsored**');
  if (s !== -1) {
    const tail = chunk.slice(s + 13);
    const stop = tail.indexOf('\n[\n');
    body = tail.slice(0, stop === -1 ? 500 : stop)
      .split('\n').map((l) => l.trim()).filter(Boolean).join(' ')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\s+/g, ' ').trim();
  }

  // The last short capitalised line before the destination link is the button.
  let offer = '';
  const j = chunk.indexOf('](https://l.facebook');
  if (j !== -1) {
    const lines = chunk.slice(Math.max(0, j - 600), j)
      .split('\n').map((l) => l.trim())
      .filter((l) => l && l.length < 42 && !/^!?\[/.test(l) && !/^https?:/.test(l))
      // A video card puts the player's scrubber where the button would be, and
      // `0:00 / 0:00` then ends up printed as the ad's offer - in the report,
      // in the gap list, and in what the model is asked to compare. Measured
      // live: two of eight cards in one run.
      .filter((l) => !/^\d{1,2}:\d{2}(\s*\/\s*\d{1,2}:\d{2})?$/.test(l))
      // Facebook's own chrome, not the advertiser's button. `Sponsored` sits in
      // the same position on cards with no call to action and was being read as
      // the offer on one card in eight.
      .filter((l) => !/^\**(sponsored|suggested for you|ad)\**$/i.test(l));
    // The markdown converter bolds the button text on some cards and not
    // others, and `**Shop Now**` and `Shop Now` are two different offers as far
    // as the gap comparison is concerned.
    if (lines.length) offer = lines[lines.length - 1].replace(/\*/g, '').trim();
  }

  // Two images can live in a card: the advertiser's avatar, which Facebook
  // serves at s60x60, and the still creative at s600x600. Take the first that
  // is not the avatar - matching the first image caught the avatar instead.
  let creative = '';
  const imgRe = /!\[[^\]]*\]\((https:\/\/[^)\s]+)\)/g;
  let im;
  while ((im = imgRe.exec(chunk)) !== null) {
    if (im[1].indexOf('s60x60') !== -1) continue;
    creative = im[1];
    break;
  }

  // Half the grid has no still at all because half of Meta advertising is
  // video, and the player leaves a duration behind instead of an image. That
  // is worth reporting rather than hiding: whether a competitor is buying
  // video or static is a media decision, not a parsing failure.
  const dur = chunk.slice(0, 2500).match(/\b(\d{1,2}:\d{2})\s*\/\s*(\d{1,2}:\d{2})/);
  const mediaType = dur ? 'video' : (creative ? 'image' : 'unknown');
  const landingUrl = unwrap(chunk);
  const host = (String(landingUrl).match(/^https?:\/\/([^/?#]+)/) || [])[1] || '';

  out.push({ json: {
    term: term,
    side: side,
    country: country,
    library_id: libraryId,
    status: status,
    started_on: startedOn,
    days_running: daysRunning,
    advertiser: adv ? adv[1].trim() : '',
    advertiser_page: adv ? adv[2] : '',
    ad_text: body.slice(0, 900),
    offer: offer,
    creative_url: creative,
    media_type: mediaType,
    video_length: dur ? dur[2] : '',
    landing_domain: host.replace(/^www\./, ''),
    landing_url: String(landingUrl).split('?')[0],
    utm_campaign: param(landingUrl, 'utm_campaign'),
    utm_content: param(landingUrl, 'utm_content'),
    multiple_versions: chunk.slice(0, 700).indexOf('multiple versions') !== -1,
    term_total_results: totalResults,
  } });
}

// A term that matched nothing still has to emit an item, or the loop's own
// bookkeeping silently loses that term and the digest cannot say it was quiet.
if (!out.length) {
  return [{ json: { term: term, side: side, country: country, ads_found: 0, term_total_results: totalResults } }];
}
return out;

// Every term has been through the loop by now, so this sees the whole run.
const cfg = $('Settings').first().json;
const provenAfter = Number(cfg.proven_after_days) || 60;
const maxPerTerm = Number(cfg.max_ads_per_term) || 8;

const rows = $input.all().map((x) => x.json).filter((r) => r && r.library_id);

// The same ad can surface under two search terms. Keep the first and record
// that it matched more than one, which is itself a signal about the advertiser.
const byId = {};
for (const r of rows) {
  if (byId[r.library_id]) {
    if (byId[r.library_id].term.indexOf(r.term) === -1) {
      byId[r.library_id].term += ', ' + r.term;
    }
    // The same creative can surface under both searches, because
    // keyword_unordered matches ad text rather than advertiser. Marking it
    // `both` stops it being counted as a gap in your coverage when it is in
    // fact an ad you are already running.
    if (byId[r.library_id].side !== r.side) byId[r.library_id].side = 'both';
    continue;
  }
  byId[r.library_id] = { ...r };
}

const all = Object.keys(byId).map((k) => byId[k]);

// Longest-running first. That is the entire thesis of this template: an ad that
// has survived a year of spend is a tested message, and a two-week-old ad is
// somebody's guess.
all.sort((a, b) => b.days_running - a.days_running);

const perTerm = {};
const kept = [];
for (const r of all) {
  const key = String(r.term).split(',')[0];
  perTerm[key] = (perTerm[key] || 0) + 1;
  if (perTerm[key] > maxPerTerm) continue;
  r.proven = r.days_running >= provenAfter;
  r.age_band =
    r.days_running >= 365 ? 'over a year' :
    r.days_running >= provenAfter ? 'proven' :
    r.days_running >= 14 ? 'testing' : 'just launched';
  kept.push(r);
}

// Never return zero items - the Data Table lookup below is a filter, and a
// branch that ends here would take the digest with it.
if (!kept.length) {
  return [{ json: { library_id: '', nothing_found: true } }];
}
return kept.map((r) => ({ json: r }));

// The comparison. This is what the run is for.
//
// Both sides came through the same loop, so `side` is the only thing separating
// them, and every number below is like-for-like by construction.
const rows = $input.all().map((x) => x.json).filter((r) => r && r.library_id);

// Belt and braces behind the IF above. If a marker row ever reaches here the
// filter empties this node, the branch dies, and a form trigger left with no
// terminating node waits forever instead of failing - which is the worst way
// for this to break, because a hung form looks like a slow run.
if (!rows.length) {
  throw new Error('No ads reached the comparison - "Anything Running?" should have routed this to the empty page.');
}

// `both` counts on each side rather than neither - an ad that matched both
// searches genuinely is running for both advertisers.
const theirs = rows.filter((r) => r.side !== 'us');
const ours = rows.filter((r) => r.side !== 'them');

// A landing domain is the closest public proxy for "what this campaign sells".
// Comparing domains rather than ad text means a rewritten headline does not
// read as a new offer.
const ourDomains = new Set(ours.map((r) => String(r.landing_domain || '').toLowerCase()));
const ourOffers = new Set(
  ours.map((r) => String(r.offer || '').toLowerCase().trim()).filter(Boolean)
);

function longest(list) {
  return list.reduce((m, r) => Math.max(m, Number(r.days_running) || 0), 0);
}

const stats = {
  their_ads: theirs.length,
  our_ads: ours.length,
  // Anything past the proven threshold has survived that much spend.
  their_proven: theirs.filter((r) => r.proven).length,
  our_proven: ours.filter((r) => r.proven).length,
  their_longest: longest(theirs),
  our_longest: longest(ours),
  // A run with no `us` term is a plain teardown rather than a comparison, and
  // the report has to say which of the two it is.
  compared: ours.length > 0,
};

// Their proven ads whose offer we are not running. Ordered longest-first, so
// the top of the list is the message they have paid to keep alive the longest.
const gaps = theirs
  .filter((r) => r.proven)
  .filter((r) => {
    const offer = String(r.offer || '').toLowerCase().trim();
    if (offer && ourOffers.has(offer)) return false;
    return !ourDomains.has(String(r.landing_domain || '').toLowerCase());
  })
  .sort((a, b) => b.days_running - a.days_running);

return rows.map((r) => ({
  json: Object.assign({}, r, {
    stats,
    is_gap: r.side !== 'us' && gaps.some((g) => g.library_id === r.library_id),
    gap_rank: gaps.findIndex((g) => g.library_id === r.library_id) + 1,
  }),
}));

// The ad says "50% off your first box". Whether that is still the offer once
// somebody clicks is a different question, and it is the one a competitor
// actually needs answered - ad copy goes stale while the landing page moves.
//
// One read per distinct domain, longest-running ad first, capped. Reading the
// same domain five times because five ads point at it is spend for nothing.
const cfg = $('Settings').first().json;
const cap = Number(cfg.landing_pages_to_read) || 3;

// Read the new ads by name, not from this node's input. The Data Table insert
// above emits the *rows it wrote* - library_id, advertiser, first_seen - and
// nothing else, so `$input` here has no landing_url on it at all and every
// lookup silently came back empty. The node upstream of the write is the one
// still holding the whole ad.
const ads = $('Split Theirs From Yours').all()
  .map((x) => x.json).filter((r) => r && r.landing_url);
ads.sort((a, b) => b.days_running - a.days_running);

const seen = {};
const out = [];
for (const r of ads) {
  const domain = String(r.landing_domain || '');
  if (!domain || seen[domain]) continue;
  seen[domain] = true;
  out.push({ json: {
    landing_domain: domain,
    landing_url: r.landing_url,
    advertiser: r.advertiser,
    days_running: r.days_running,
  } });
  if (out.length >= cap) break;
}

// A run with nothing new still has to emit one item, or this branch ends here
// and takes the digest with it.
if (!out.length) {
  return [{ json: { landing_domain: '', landing_url: '', skip: true } }];
}
return out;

// One landing page per item. The prices and the loudest promise are pulled out
// so the digest can put the ad's claim next to what the page actually says.
const planned = $('Pick Landing Pages To Read').all().map((x) => x.json);
const items = $input.all();

const out = [];
for (let i = 0; i < items.length; i++) {
  const plan = planned[i] || {};
  if (plan.skip) continue;

  const raw = items[i].json;
  const md = typeof raw === 'string' ? raw : (raw.data || raw.body || '');
  if (!md || md.length < 200) {
    out.push({ json: { ...plan, live_offer: '', prices: [], note: 'page could not be read' } });
    continue;
  }

  // Currency amounts, deduped and kept in page order. The first few are almost
  // always the headline price and the anchor it is discounted from.
  const prices = [];
  const priceRe = /(?:[$\u00a3\u20ac]\s?\d[\d,]*(?:\.\d{2})?)/g;
  let m;
  while ((m = priceRe.exec(md)) !== null) {
    const p = m[0].replace(/\s/g, '');
    if (prices.indexOf(p) === -1) prices.push(p);
    if (prices.length >= 8) break;
  }

  // The discount language is what to compare against the ad, not the prose.
  const offers = [];
  const offerRe = /([^.\n]{0,60}(?:\d{1,3}%\s*off|free\s+(?:trial|shipping|meals?|box|month)|first\s+(?:box|order|month)|save\s+[$\u00a3\u20ac]?\d+)[^.\n]{0,60})/gi;
  while ((m = offerRe.exec(md)) !== null) {
    const line = m[1].replace(/\s+/g, ' ').trim();
    if (line && offers.indexOf(line) === -1) offers.push(line);
    if (offers.length >= 3) break;
  }

  out.push({ json: {
    ...plan,
    live_offer: offers.join(' | ').slice(0, 300),
    prices: prices.slice(0, 5),
  } });
}

if (!out.length) {
  return [{ json: { landing_domain: '', live_offer: '', prices: [] } }];
}
return out;

