// The page whoever filled the form is left looking at. Rendered raw by the Form
// ending node, so this is real HTML rather than an email body.
const form = $('Brief Me On A Competitor').first().json;
const cfg = $('Settings').first().json;
const rows = $('Split Theirs From Yours').all()
  .map((x) => x.json).filter((r) => r && r.library_id);

const stats = (rows[0] && rows[0].stats) || {};
const theirs = rows.filter((r) => r.side === 'them');
const gaps = theirs.filter((r) => r.is_gap).sort((a, b) => a.gap_rank - b.gap_rank);

let angles = '';
try { angles = String($('Name The Angles').first().json.text || '').trim(); } catch (e) { angles = ''; }
let gapNote = '';
try { gapNote = String($('Find The Gaps').first().json.text || '').trim(); } catch (e) { gapNote = ''; }

function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// What the landing pages actually say, keyed by domain, so each card can put
// the ad's promise next to the live offer.
const live = {};
try {
  for (const x of $('Read The Live Offer').all()) {
    const j = x.json || {};
    if (j.landing_domain) live[j.landing_domain] = j;
  }
} catch (e) { /* no page was readable on this run */ }

const F = 'system-ui,-apple-system,Segoe UI,sans-serif';
const provenAfter = Number(cfg.proven_after_days) || 60;

const head =
  '<div style="max-width:760px;margin:0 auto;text-align:left">' +
  '<h2 style="font:600 22px ' + F + ';margin:0 0 6px">' +
  esc(form['Competitor brand or category']) + ' - what is actually running</h2>' +
  '<p style="font:14px/1.5 ' + F + ';color:#555;margin:0 0 18px">' +
  stats.their_ads + ' live ads in ' + esc(rows[0] ? rows[0].country : '') + ', ' +
  stats.their_proven + ' running longer than ' + provenAfter + ' days. ' +
  'Longest: <b>' + stats.their_longest + ' days</b>.' +
  (stats.compared
    ? ' You have ' + stats.our_ads + ' live, ' + stats.our_proven +
      ' proven, longest ' + stats.our_longest + ' days.'
    : ' No brand of your own was entered, so this is a teardown rather than a comparison.') +
  '</p>';

function panel(text, tone) {
  return '<div style="font:14px/1.6 ' + F + ';background:' + tone +
    ';border-radius:8px;padding:14px 16px;margin:0 0 18px;white-space:pre-wrap">' +
    esc(text) + '</div>';
}

const brief = angles ? panel(angles, '#f6f7f9') : '';
const gapPanel = (stats.compared && gapNote) ? panel(gapNote, '#fff6e8') : '';

const gapList = gaps.length
  ? '<h3 style="font:600 16px ' + F + ';margin:0 0 8px">' +
    (stats.compared
      ? 'Proven offers of theirs you are not running'
      : 'Their longest-running offers') +
    '</h3>' +
    '<ol style="font:14px/1.6 ' + F + ';margin:0 0 22px;padding-left:20px">' +
    gaps.slice(0, 8).map((r) =>
      '<li><b>' + esc(r.offer || r.ad_text.slice(0, 60)) + '</b> - ' +
      r.days_running + ' days, lands on ' + esc(r.landing_domain) + '</li>'
    ).join('') + '</ol>'
  : '';

const cards = theirs.slice(0, 20).map((r) => {
  const badge =
    '<span style="background:' + (r.proven ? '#0a7d33' : '#666') +
    ';color:#fff;font:600 11px ' + F + ';padding:2px 7px;border-radius:10px">' +
    r.days_running + ' days - ' + esc(r.age_band) + '</span>';
  const flag = r.is_gap
    ? ' <span style="background:#c2410c;color:#fff;font:600 11px ' + F +
      ';padding:2px 7px;border-radius:10px">not in your ads</span>'
    : '';
  const img = r.creative_url
    ? '<img src="' + esc(r.creative_url) + '" alt="" width="150" style="border-radius:6px;display:block">'
    : '<div style="width:150px;height:110px;border-radius:6px;background:#eceef1;color:#666;' +
      'font:600 12px ' + F + ';display:flex;align-items:center;justify-content:center">' +
      (r.media_type === 'video' ? 'video ad ' + esc(r.video_length) : 'no still') + '</div>';
  const lp = live[r.landing_domain];
  const onPage = (lp && (lp.live_offer || (lp.prices || []).length))
    ? '<div style="color:#0a7d33;margin-top:4px">On the page now: ' +
      esc(lp.live_offer || '') +
      ((lp.prices || []).length ? ' (' + esc(lp.prices.slice(0, 3).join(', ')) + ')' : '') +
      '</div>'
    : '';
  const utm = r.utm_campaign
    ? '<div style="font:12px ui-monospace,monospace;color:#777;margin-top:6px;word-break:break-all">' +
      esc(r.utm_campaign) + '</div>'
    : '';
  return '' +
    '<table style="border-collapse:collapse;margin:0 0 18px;width:100%"><tr>' +
    '<td style="vertical-align:top;width:160px">' + img + '</td>' +
    '<td style="vertical-align:top;font:14px/1.5 ' + F + '">' +
    badge + flag +
    ' <a href="' + esc(r.advertiser_page) + '" style="font-weight:600;color:#111;text-decoration:none">' +
    esc(r.advertiser) + '</a>' +
    '<div style="color:#222;margin:6px 0">' + esc(r.ad_text).slice(0, 420) + '</div>' +
    '<div style="color:#555">' +
    (r.offer ? '<b>' + esc(r.offer) + '</b> to ' : 'Lands on ') + esc(r.landing_domain) +
    (r.multiple_versions ? ' - split testing several versions' : '') + '</div>' +
    onPage + utm +
    '<div style="color:#999;font-size:12px;margin-top:4px">matched: ' + esc(r.term) +
    ' - library ' + esc(r.library_id) + '</div>' +
    '</td></tr></table>';
}).join('');

